function validate(input) {
  const [{ Customers = [] }] = input;
  const seen = new Set();
  for (const [id] of Customers) {
    if (id === null) return 'Every customer needs a customer_id.';
    if (!Number.isInteger(id) || id < 1 || id > 100) return `customer_id ${id} is outside 1..100.`;
    if (seen.has(id)) return `customer_id ${id} appears twice.`;
    seen.add(id);
  }
  return null;
}

