function generate(rand, size) {
  const names = ['Alice', 'Bob', 'Charlie', 'Dana', 'Eve', 'Femi'];
  const small = size === 'small';
  // Small tables draw from 1..12 (sometimes one far id); large ones fill most of 1..100.
  const pool = [];
  const top = small ? 12 : 100;
  for (let id = 1; id <= top; id++) pool.push(id);
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const count = small ? Math.floor(rand() * 9) : 60 + Math.floor(rand() * 41);
  const ids = pool.slice(0, count);
  if (small && ids.length && rand() < 0.2) ids[0] = 90 + Math.floor(rand() * 11);
  const unique = [...new Set(ids)];
  const Customers = unique.map(id => [id, names[Math.floor(rand() * names.length)]]);
  return [{ Customers }];
}
